class FsrsParityTest {
    private data class Step(val rating: Rating, val at: Long)
    private data class Expected(
        val due: Long,
        val stability: Double,
        val difficulty: Double,
        val elapsedDays: Int,
        val scheduledDays: Int,
        val reps: Int,
        val lapses: Int,
        val learningSteps: Int,
        val state: State,
        val lastReview: Long?,
    )

    private fun runSequence(start: Long, steps: List<Step>, expected: List<Expected>) {
        val scheduler = Scheduler()
        var card = createEmptyCard(start)
        steps.forEachIndexed { i, step ->
            card = scheduler.next(card, step.at, step.rating)
            val e = expected[i]
            val at = "after ${step.rating} at ${step.at}"
            assertEquals(e.due, card.due, "due $at")
            assertEquals(e.stability, card.stability, 1e-6, "stability $at")
            assertEquals(e.difficulty, card.difficulty, 1e-6, "difficulty $at")
            assertEquals(e.elapsedDays, card.elapsedDays, "elapsedDays $at")
            assertEquals(e.scheduledDays, card.scheduledDays, "scheduledDays $at")
            assertEquals(e.reps, card.reps, "reps $at")
            assertEquals(e.lapses, card.lapses, "lapses $at")
            assertEquals(e.learningSteps, card.learningSteps, "learningSteps $at")
            assertEquals(e.state, card.state, "state $at")
            assertEquals(e.lastReview, card.lastReview, "lastReview $at")
        }
    }

